if ( ! defined( 'ABSPATH' ) ) exit;

function bk_ui_review_defaults() { return array(
    'hero_title' => 'آموزش خیاطی، مهارتی برای یک زندگی خلاق',
    'hero_text' => 'با آموزش‌های پروژه‌محور، مهارتت را به یک مسیر واقعی برای ساختن و درآمدزایی تبدیل کن.',
    'hero_primary' => 'شروع یادگیری',
    'hero_secondary' => 'دوره‌ها را ببین',
    'benefit_4_icon' => '',
    'benefit_4_title' => 'تجربه‌ای مطمئن',
    'benefit_4_text' => 'آموزش پروژه‌محور',
); }
function bk_ui_review_get( $key ) { $s=wp_parse_args(get_option('bk_ui_review_settings',array()),bk_ui_review_defaults()); return $s[$key] ?? ''; }
add_action('admin_menu',function(){ add_submenu_page('bk-core-settings','استاندارد رابط کاربری','استاندارد رابط کاربری','manage_options','bk-ui-review','bk_ui_review_page'); });
add_action('admin_init',function(){ register_setting('bk_ui_review_group','bk_ui_review_settings',array('sanitize_callback'=>function($input){$d=bk_ui_review_defaults();$o=array();foreach($d as $k=>$v)$o[$k]=isset($input[$k])?sanitize_textarea_field($input[$k]):$v;if(!empty($input['benefit_4_icon']))$o['benefit_4_icon']=esc_url_raw($input['benefit_4_icon']);return $o;})); });
function bk_ui_review_page(){if(!current_user_can('manage_options'))return;$s=wp_parse_args(get_option('bk_ui_review_settings',array()),bk_ui_review_defaults());?>
<div class="wrap" dir="rtl"><h1>استاندارد رابط کاربری</h1><p>محتوای هیرو و مزیت چهارم از این بخش مدیریت می‌شود.</p><form method="post" action="options.php"><?php settings_fields('bk_ui_review_group');?><h2>هیرو</h2><table class="form-table"><tr><th>عنوان</th><td><input class="large-text" name="bk_ui_review_settings[hero_title]" value="<?php echo esc_attr($s['hero_title']);?>"></td></tr><tr><th>توضیح</th><td><textarea class="large-text" rows="3" name="bk_ui_review_settings[hero_text]"><?php echo esc_textarea($s['hero_text']);?></textarea></td></tr><tr><th>دکمه اصلی</th><td><input class="regular-text" name="bk_ui_review_settings[hero_primary]" value="<?php echo esc_attr($s['hero_primary']);?>"></td></tr><tr><th>دکمه دوم</th><td><input class="regular-text" name="bk_ui_review_settings[hero_secondary]" value="<?php echo esc_attr($s['hero_secondary']);?>"></td></tr></table><h2>مزیت چهارم</h2><table class="form-table"><tr><th>آیکن</th><td><input class="large-text" name="bk_ui_review_settings[benefit_4_icon]" value="<?php echo esc_attr($s['benefit_4_icon']);?>"></td></tr><tr><th>عنوان</th><td><input class="regular-text" name="bk_ui_review_settings[benefit_4_title]" value="<?php echo esc_attr($s['benefit_4_title']);?>"></td></tr><tr><th>توضیح</th><td><input class="regular-text" name="bk_ui_review_settings[benefit_4_text]" value="<?php echo esc_attr($s['benefit_4_text']);?>"></td></tr></table><?php submit_button('ذخیره تنظیمات');?></form></div><?php }
add_action('wp_head',function(){if(is_admin())return;?>
