add_action('wp_footer',function(){if(is_admin())return;?><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.bk-dots').forEach(function(d){var g=d.previousElementSibling;if(g&&g.querySelectorAll('.bk-course-card').length<=1)d.style.display='none';});});</script><?php },99);
add_filter('wp_nav_menu_items',function($items,$args){if(empty($args->theme_location)||'primary'!==$args->theme_location||is_front_page())return $items;$home=home_url('/');foreach(array('courses','categories','mentors','about','testimonials','contact') as $id)$items=str_replace('href="#'.$id.'"','href="'.esc_url($home.'#'.$id).'"',$items);return $items;},20,2);
